7	import type { Config } from '../config/config.js';
8	import { SessionSummaryService } from './sessionSummaryService.js';
9	import { BaseLlmClient } from '../core/baseLlmClient.js';
10	import { debugLogger } from '../utils/debugLogger.js';
11	import {
12	  SESSION_FILE_PREFIX,
13	  type ConversationRecord,
14	} from './chatRecordingService.js';
15	import fs from 'node:fs/promises';
16	import path from 'node:path';
17	
18	const MIN_MESSAGES_FOR_SUMMARY = 1;
19	
20	/**
21	 * Generates and saves a summary for a session file.
22	 */
23	async function generateAndSaveSummary(
24	  config: Config,
25	  sessionPath: string,
26	): Promise<void> {
27	  // Read session file
28	  const content = await fs.readFile(sessionPath, 'utf-8');
29	  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
30	  const conversation: ConversationRecord = JSON.parse(content);
31	
32	  // Skip if summary already exists
33	  if (conversation.summary) {
34	    debugLogger.debug(
35	      `[SessionSummary] Summary already exists for ${sessionPath}, skipping`,
36	    );
37	    return;
38	  }
39	
40	  // Skip if no messages
41	  if (conversation.messages.length === 0) {
42	    debugLogger.debug(
43	      `[SessionSummary] No messages to summarize in ${sessionPath}`,
44	    );
45	    return;
46	  }
47	
48	  // Create summary service
49	  const contentGenerator = config.getContentGenerator();
50	  if (!contentGenerator) {
51	    debugLogger.debug(
52	      '[SessionSummary] Content generator not available, skipping summary generation',
53	    );
54	    return;
55	  }
56	  const baseLlmClient = new BaseLlmClient(contentGenerator, config);
57	  const summaryService = new SessionSummaryService(baseLlmClient);
58	
59	  // Generate summary
60	  const summary = await summaryService.generateSummary({
61	    messages: conversation.messages,
62	  });
63	
64	  if (!summary) {
65	    debugLogger.warn(
66	      `[SessionSummary] Failed to generate summary for ${sessionPath}`,
67	    );
68	    return;
69	  }
70	
71	  // Re-read the file before writing to handle race conditions
72	  const freshContent = await fs.readFile(sessionPath, 'utf-8');
73	  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
74	  const freshConversation: ConversationRecord = JSON.parse(freshContent);
75	
76	  // Check if summary was added by another process
77	  if (freshConversation.summary) {
78	    debugLogger.debug(
79	      `[SessionSummary] Summary was added by another process for ${sessionPath}`,
80	    );
81	    return;
82	  }
83	
84	  // Add summary and write back
85	  freshConversation.summary = summary;
86	  freshConversation.lastUpdated = new Date().toISOString();
87	  await fs.writeFile(sessionPath, JSON.stringify(freshConversation, null, 2));
88	  debugLogger.debug(
89	    `[SessionSummary] Saved summary for ${sessionPath}: "${summary}"`,
90	  );
91	}
