93	/**
94	 * Finds the most recently created session that needs a summary.
95	 * Returns the path if it needs a summary, null otherwise.
96	 */
97	export async function getPreviousSession(
98	  config: Config,
99	): Promise<string | null> {
100	  try {
101	    const chatsDir = path.join(config.storage.getProjectTempDir(), 'chats');
102	
103	    // Check if chats directory exists
104	    try {
105	      await fs.access(chatsDir);
106	    } catch {
107	      debugLogger.debug('[SessionSummary] No chats directory found');
108	      return null;
109	    }
110	
111	    // List session files
112	    const allFiles = await fs.readdir(chatsDir);
113	    const sessionFiles = allFiles.filter(
114	      (f) => f.startsWith(SESSION_FILE_PREFIX) && f.endsWith('.json'),
115	    );
116	
117	    if (sessionFiles.length === 0) {
118	      debugLogger.debug('[SessionSummary] No session files found');
119	      return null;
120	    }
121	
122	    // Sort by filename descending (most recently created first)
123	    // Filename format: session-YYYY-MM-DDTHH-MM-XXXXXXXX.json
124	    sessionFiles.sort((a, b) => b.localeCompare(a));
125	
126	    // Check the most recently created session
127	    const mostRecentFile = sessionFiles[0];
128	    const filePath = path.join(chatsDir, mostRecentFile);
129	
130	    try {
131	      const content = await fs.readFile(filePath, 'utf-8');
132	      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
133	      const conversation: ConversationRecord = JSON.parse(content);
134	
135	      if (conversation.summary) {
136	        debugLogger.debug(
137	          '[SessionSummary] Most recent session already has summary',
138	        );
139	        return null;
140	      }
141	
142	      // Only generate summaries for sessions with more than 1 user message
143	      const userMessageCount = conversation.messages.filter(
144	        (m) => m.type === 'user',
145	      ).length;
146	      if (userMessageCount <= MIN_MESSAGES_FOR_SUMMARY) {
147	        debugLogger.debug(
148	          `[SessionSummary] Most recent session has ${userMessageCount} user message(s), skipping (need more than ${MIN_MESSAGES_FOR_SUMMARY})`,
149	        );
150	        return null;
151	      }
152	
153	      return filePath;
154	    } catch {
155	      debugLogger.debug('[SessionSummary] Could not read most recent session');
156	      return null;
157	    }
158	  } catch (error) {
159	    debugLogger.debug(
160	      `[SessionSummary] Error finding previous session: ${error instanceof Error ? error.message : String(error)}`,
161	    );
162	    return null;
163	  }
164	}
165	
166	/**
167	 * Generates summary for the previous session if it lacks one.
168	 * This is designed to be called fire-and-forget on startup.
169	 */
170	export async function generateSummary(config: Config): Promise<void> {
171	  try {
172	    const sessionPath = await getPreviousSession(config);
173	    if (sessionPath) {
174	      await generateAndSaveSummary(config, sessionPath);
175	    }
176	  } catch (error) {
177	    // Log but don't throw - we want graceful degradation
178	    debugLogger.warn(
179	      `[SessionSummary] Error generating summary: ${error instanceof Error ? error.message : String(error)}`,
180	    );
181	  }
182	}
