81	function isLockInfo(value: unknown): value is LockInfo {
82	  return (
83	    typeof value === 'object' &&
84	    value !== null &&
85	    'pid' in value &&
86	    typeof value.pid === 'number' &&
87	    'startedAt' in value &&
88	    typeof value.startedAt === 'string'
89	  );
