128	/**
129	 * Attempts to acquire an exclusive lock file using O_CREAT | O_EXCL.
130	 * Returns true if the lock was acquired, false if another instance owns it.
131	 */
132	export async function tryAcquireLock(
133	  lockPath: string,
134	  retries = 1,
135	): Promise<boolean> {
136	  const lockInfo: LockInfo = {
137	    pid: process.pid,
138	    startedAt: new Date().toISOString(),
139	  };
140	
141	  try {
142	    // Atomic create-if-not-exists
143	    const fd = await fs.open(
144	      lockPath,
145	      fsConstants.O_CREAT | fsConstants.O_EXCL | fsConstants.O_WRONLY,
146	    );
147	    try {
148	      await fd.writeFile(JSON.stringify(lockInfo));
149	    } finally {
150	      await fd.close();
151	    }
152	    return true;
153	  } catch (error: unknown) {
154	    if (isNodeError(error) && error.code === 'EEXIST') {
155	      // Lock exists — check if it's stale
156	      if (retries > 0 && (await isLockStale(lockPath))) {
157	        debugLogger.debug('[MemoryService] Cleaning up stale lock file');
158	        await releaseLock(lockPath);
159	        return tryAcquireLock(lockPath, retries - 1);
160	      }
161	      debugLogger.debug(
162	        '[MemoryService] Lock held by another instance, skipping',
163	      );
164	      return false;
165	    }
166	    throw error;
167	  }
168	}
