170	/**
171	 * Checks if a lock file is stale (owner PID is dead or lock is too old).
172	 */
173	export async function isLockStale(lockPath: string): Promise<boolean> {
174	  try {
175	    const content = await fs.readFile(lockPath, 'utf-8');
176	    const parsed: unknown = JSON.parse(content);
177	    if (!isLockInfo(parsed)) {
178	      return true; // Invalid lock data — treat as stale
179	    }
180	    const lockInfo = parsed;
181	
182	    // Check if PID is still alive
183	    try {
184	      process.kill(lockInfo.pid, 0);
185	    } catch {
186	      // PID is dead — lock is stale
187	      return true;
188	    }
189	
190	    // Check if lock is too old
191	    const lockAge = Date.now() - new Date(lockInfo.startedAt).getTime();
192	    if (lockAge > LOCK_STALE_MS) {
193	      return true;
194	    }
195	
196	    return false;
197	  } catch {
198	    // Can't read lock — treat as stale
199	    return true;
200	  }
201	}
