225	  try {
226	    const content = await fs.readFile(statePath, 'utf-8');
227	    const parsed: unknown = JSON.parse(content);
228	    if (!isExtractionState(parsed)) {
229	      return { runs: [] };
230	    }
231	
232	    const runs: ExtractionRun[] = [];
233	    for (const run of parsed.runs) {
234	      if (!isExtractionRun(run)) continue;
235	      runs.push({
236	        runAt: run.runAt,
237	        sessionIds: run.sessionIds.filter(
238	          (sid): sid is string => typeof sid === 'string',
239	        ),
240	        skillsCreated: run.skillsCreated.filter(
241	          (sk): sk is string => typeof sk === 'string',
242	        ),
243	      });
244	    }
245	
246	    return { runs };
247	  } catch (error) {
248	    debugLogger.debug(
249	      '[MemoryService] Failed to read extraction state:',
250	      error,
251	    );
252	    return { runs: [] };
253	  }
254	}
