50	function hasProperty<T extends string>(
51	  obj: unknown,
52	  prop: T,
53	): obj is { [key in T]: unknown } {
54	  return obj !== null && typeof obj === 'object' && prop in obj;
55	}
56	
57	function isStringProperty<T extends string>(
58	  obj: unknown,
59	  prop: T,
60	): obj is { [key in T]: string } {
61	  return hasProperty(obj, prop) && typeof obj[prop] === 'string';
62	}
63	
64	function isObjectProperty<T extends string>(
65	  obj: unknown,
66	  prop: T,
67	): obj is { [key in T]: object } {
68	  return (
69	    hasProperty(obj, prop) &&
70	    obj[prop] !== null &&
71	    typeof obj[prop] === 'object'
72	  );
73	}
74	
75	function isRewindRecord(record: unknown): record is RewindRecord {
76	  return isStringProperty(record, '$rewindTo');
77	}
78	
79	function isMessageRecord(record: unknown): record is MessageRecord {
80	  return isStringProperty(record, 'id');
81	}
82	
83	function isMetadataUpdateRecord(
84	  record: unknown,
85	): record is MetadataUpdateRecord {
86	  return isObjectProperty(record, '$set');
87	}
88	
89	function isPartialMetadataRecord(
90	  record: unknown,
91	): record is PartialMetadataRecord {
92	  return (
93	    isStringProperty(record, 'sessionId') &&
94	    isStringProperty(record, 'projectHash')
95	  );
96	}
97	
98	function isTextPart(part: unknown): part is { text: string } {
99	  return isStringProperty(part, 'text');
100	}
101	
102	function isSessionIdRecord(record: unknown): record is { sessionId: string } {
103	  return isStringProperty(record, 'sessionId');
104	}
