106	export async function loadConversationRecord(
107	  filePath: string,
108	  options?: LoadConversationOptions,
109	): Promise<
110	  | (ConversationRecord & {
111	      messageCount?: number;
112	      firstUserMessage?: string;
113	      hasUserOrAssistantMessage?: boolean;
114	    })
115	  | null
116	> {
117	  if (!fs.existsSync(filePath)) {
118	    return null;
119	  }
120	
121	  try {
122	    const fileStream = fs.createReadStream(filePath);
123	    const rl = readline.createInterface({
124	      input: fileStream,
125	      crlfDelay: Infinity,
126	    });
127	
128	    let metadata: Partial<ConversationRecord> = {};
129	    const messagesMap = new Map<string, MessageRecord>();
130	    const messageIds: string[] = [];
131	    let firstUserMessageStr: string | undefined;
132	    let hasUserOrAssistant = false;
133	
134	    for await (const line of rl) {
135	      if (!line.trim()) continue;
136	      try {
137	        const record = JSON.parse(line) as unknown;
138	        if (isRewindRecord(record)) {
139	          const rewindId = record.$rewindTo;
140	          if (options?.metadataOnly) {
141	            const idx = messageIds.indexOf(rewindId);
142	            if (idx !== -1) {
143	              messageIds.splice(idx);
144	            } else {
145	              messageIds.length = 0;
146	            }
147	            // For metadataOnly we can't perfectly un-track hasUserOrAssistant if it was rewinded,
148	            // but we can assume false if messageIds is empty.
149	            if (messageIds.length === 0) hasUserOrAssistant = false;
150	          } else {
151	            let found = false;
152	            const idsToDelete: string[] = [];
153	            for (const [id] of messagesMap) {
154	              if (id === rewindId) found = true;
155	              if (found) idsToDelete.push(id);
156	            }
157	            if (found) {
158	              for (const id of idsToDelete) {
159	                messagesMap.delete(id);
160	              }
161	            } else {
162	              messagesMap.clear();
163	            }
164	          }
165	        } else if (isMessageRecord(record)) {
166	          const id = record.id;
167	          if (
168	            hasProperty(record, 'type') &&
169	            (record.type === 'user' || record.type === 'gemini')
170	          ) {
171	            hasUserOrAssistant = true;
172	          }
173	          // Track message count and first user message
174	          if (options?.metadataOnly) {
175	            messageIds.push(id);
176	          }
177	          if (
178	            !firstUserMessageStr &&
179	            hasProperty(record, 'type') &&
180	            record['type'] === 'user' &&
181	            hasProperty(record, 'content') &&
182	            record['content']
183	          ) {
184	            // Basic extraction of first user message for display
185	            const rawContent = record['content'];
186	            if (Array.isArray(rawContent)) {
187	              firstUserMessageStr = rawContent
188	                .map((p: unknown) => (isTextPart(p) ? p['text'] : ''))
189	                .join('');
190	            } else if (typeof rawContent === 'string') {
191	              firstUserMessageStr = rawContent;
192	            }
193	          }
194	
195	          if (!options?.metadataOnly) {
196	            messagesMap.set(id, record);
197	            if (
198	              options?.maxMessages &&
199	              messagesMap.size > options.maxMessages
200	            ) {
201	              const firstKey = messagesMap.keys().next().value;
202	              if (typeof firstKey === 'string') messagesMap.delete(firstKey);
203	            }
204	          }
205	        } else if (isMetadataUpdateRecord(record)) {
206	          // Metadata update
207	          metadata = {
208	            ...metadata,
209	            ...record.$set,
210	          };
211	        } else if (isPartialMetadataRecord(record)) {
212	          // Initial metadata line
213	          metadata = { ...metadata, ...record };
214	        }
215	      } catch {
216	        // ignore parse errors on individual lines
217	      }
218	    }
219	
220	    if (!metadata.sessionId || !metadata.projectHash) {
221	      return await parseLegacyRecordFallback(filePath, options);
222	    }
223	
224	    return {
