  config: Config,
): Promise<string | null> {
  try {
    const chatsDir = path.join(config.storage.getProjectTempDir(), 'chats');

    // Check if chats directory exists
    try {
      await fs.access(chatsDir);
    } catch {
      debugLogger.debug('[SessionSummary] No chats directory found');
      return null;
    }

    // List session files (both legacy .json and line-delimited .jsonl).
    const allFiles = await fs.readdir(chatsDir);
    const sessionFiles = allFiles.filter(
      (f) =>
        f.startsWith(SESSION_FILE_PREFIX) &&
        (f.endsWith('.json') || f.endsWith('.jsonl')),
    );

    if (sessionFiles.length === 0) {
      debugLogger.debug('[SessionSummary] No session files found');
      return null;
    }

    // Stat each file so we can visit candidates most-recently-modified first.
    // The filesystem mtime is a cheap upper bound for the content `lastUpdated`
    // (a file's mtime is always >= the last timestamp it recorded), so once we
    // reach a file whose mtime predates the best candidate found so far, no
    // remaining file can be newer and we can stop early.
    const statted: Array<{ filePath: string; mtimeMs: number }> = [];
    for (const file of sessionFiles) {
      const filePath = path.join(chatsDir, file);
      try {
        const stat = await fs.stat(filePath);
        statted.push({ filePath, mtimeMs: stat.mtimeMs });
      } catch {
        // Skip files we can't stat.
      }
    }
    statted.sort((a, b) => b.mtimeMs - a.mtimeMs);

    const activeSessionId = config.getSessionId?.();

    let best:
      | { filePath: string; lastUpdatedMs: number; needsSummary: boolean }
      | null = null;

    for (const { filePath, mtimeMs } of statted) {
