import type { Config } from '../config/config.js';
import { SessionSummaryService } from './sessionSummaryService.js';
import { BaseLlmClient } from '../core/baseLlmClient.js';
import { debugLogger } from '../utils/debugLogger.js';
import {
  SESSION_FILE_PREFIX,
  loadConversationRecord,
  type ConversationRecord,
} from './chatRecordingService.js';
import fs from 'node:fs/promises';
import path from 'node:path';

const MIN_MESSAGES_FOR_SUMMARY = 1;

/**
 * Returns true if the given session file is a line-delimited (JSONL) session.
 */
function isJsonlSession(sessionPath: string): boolean {
  return sessionPath.endsWith('.jsonl');
}

/**
 * Generates and saves a summary for a session file.
 *
 * For line-delimited (JSONL) sessions the summary is appended as a metadata
 * update record ({ "$set": { "summary": ... } }) so the file is never
 * rewritten and any concurrently-appended `lastUpdated` is preserved.
 *
 * For legacy monolithic JSON sessions the summary field is updated in place
 * and the file is rewritten, preserving the existing `lastUpdated`.
 */
async function generateAndSaveSummary(
  config: Config,
  sessionPath: string,
): Promise<void> {
  const jsonl = isJsonlSession(sessionPath);

  // Load the session (metadata + messages) so we can build the summary.
  const conversation = await loadConversationRecord(sessionPath);
  if (!conversation) {
    debugLogger.debug(
      `[SessionSummary] Could not load session for summary: ${sessionPath}`,
    );
    return;
  }

  // Never summarize the currently-active session.
  const activeSessionId = config.getSessionId?.();
  if (activeSessionId && conversation.sessionId === activeSessionId) {
    debugLogger.debug(
      `[SessionSummary] Skipping active session ${sessionPath}`,
    );
    return;
  }

  // Skip if summary already exists
  if (conversation.summary) {
    debugLogger.debug(
      `[SessionSummary] Summary already exists for ${sessionPath}, skipping`,
    );
    return;
  }

  // Skip if no messages
  if (conversation.messages.length === 0) {
    debugLogger.debug(
      `[SessionSummary] No messages to summarize in ${sessionPath}`,
    );
    return;
  }

  // Create summary service
  const contentGenerator = config.getContentGenerator();
  if (!contentGenerator) {
    debugLogger.debug(
      '[SessionSummary] Content generator not available, skipping summary generation',
    );
    return;
